import { Component } from '@angular/core';
import { ToastService } from '../toast.service';
import { Router, RouterModule } from '@angular/router';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'app-state-sidebar',
  standalone: true,
  imports: [CommonModule,RouterModule],
  templateUrl: './state-sidebar.component.html',
  styleUrl: './state-sidebar.component.scss'
})
export class StateSidebarComponent {
    constructor(
      private router: Router,
      private toastService: ToastService
    ) { }
    goHome() {
      if (this.router.url === '/homepage') {
        this.toastService.showToast('You are already on Home page', 'success');
      } else {
        this.router.navigateByUrl('/homepage');
      }
    }
}
